INSERT INTO sink WITH     order_details AS (         SELECT o.user_id         FROM Orders o     ),     user_elements AS (         SELECT             u.id AS user_id         FROM (           SELECT '2' AS id, '2' AS order_user_id           UNION ALL           SELECT '1' AS id, '2' AS order_user_id           UNION ALL           SELECT '5' AS id, '5' AS order_user_id         ) u         LEFT JOIN order_details od             ON od.user_id = u.order_user_id     ) SELECT ue.user_id, us.name, COUNT(*) AS cnt FROM user_elements ue INNER JOIN Users us ON ue.user_id = us.user_id LEFT JOIN Payments p ON ue.user_id = p.user_id GROUP BY ue.user_id, us.name;
